/**
 * Every favicon / app icon / PWA icon the app references exists in public/, and the icon set is
 * the CareLinkAI heart mark (generated by scripts/generate-brand-icons.mjs), not the old "C" square.
 */
import fs from 'fs';
import path from 'path';

const pub = (p: string) => path.join(process.cwd(), 'public', p.replace(/^\//, ''));
const read = (p: string) => fs.readFileSync(path.join(process.cwd(), p), 'utf8');

describe('brand icon references resolve to real files', () => {
  it('layout.tsx <link> icons', () => {
    const refs = Array.from(read('src/app/layout.tsx').matchAll(/href="(\/(?:icons\/[^"]+|favicon\.[a-z]+))"/g)).map((m) => m[1]);
    expect(refs).toEqual(expect.arrayContaining(['/icons/apple-touch-icon.png', '/favicon.ico']));
    for (const r of refs) expect(fs.existsSync(pub(r))).toBe(true);
  });

  it('manifest.json icons and shortcut icons', () => {
    const m = JSON.parse(read('public/manifest.json'));
    const srcs: string[] = [...m.icons.map((i: { src: string }) => i.src), ...(m.shortcuts ?? []).flatMap((s: { icons?: Array<{ src: string }> }) => (s.icons ?? []).map((i) => i.src))];
    expect(srcs.length).toBeGreaterThan(8);
    for (const s of srcs) expect(fs.existsSync(pub(s))).toBe(true);
  });

  it('service-worker precache, push notification icons and browserconfig', () => {
    const sw = read('public/sw.js');
    const core = sw.slice(sw.indexOf('const CORE_ASSETS'), sw.indexOf('];', sw.indexOf('const CORE_ASSETS')));
    const files = [
      ...Array.from(core.matchAll(/'(\/icons\/[^']+)'/g)).map((m) => m[1]),
      ...Array.from(sw.matchAll(/'(\/icons\/[^']+\.png)'/g)).map((m) => m[1]),
      ...Array.from(read('public/browserconfig.xml').matchAll(/src="([^"]+)"/g)).map((m) => m[1]),
      ...['src/hooks/usePWAFeatures.ts', 'src/app/api/push/send/route.ts', 'src/app/api/push/subscribe/route.ts'].flatMap((f) => Array.from(read(f).matchAll(/'(\/icons\/[^']+)'/g)).map((m) => m[1])),
    ];
    expect(files).toEqual(expect.arrayContaining(['/icons/favicon.ico', '/icons/badge-96x96.png', '/icons/icon-192x192.png']));
    for (const f of new Set(files)) expect(fs.existsSync(pub(f))).toBe(true);
  });
});

describe('icon set is the heart mark, not the "C" placeholder', () => {
  it('no SVG icon draws the old "C" letter tile', () => {
    for (const f of fs.readdirSync(pub('/icons')).filter((n) => n.endsWith('.svg'))) {
      expect(read(`public/icons/${f}`)).not.toMatch(/<text[^>]*>C<\/text>/);
    }
  });

  it('favicon.ico is a real multi-size icon (16, 32, 48)', () => {
    const b = fs.readFileSync(pub('/favicon.ico'));
    expect(b.readUInt16LE(2)).toBe(1); // type: icon
    const n = b.readUInt16LE(4);
    expect(Array.from({ length: n }, (_, i) => b.readUInt8(6 + i * 16))).toEqual([16, 32, 48]);
  });
});

describe('icon URLs are served, not 404ed by the middleware', () => {
  // The unknown-path rule rewrites any path the middleware runs on (and doesn't know) to 404,
  // so static icon files must be excluded by the matcher like /images/.
  const src = read('src/middleware.ts');
  const m = src.match(/'(\/\(\(\?!_next\/[^']+)'/);
  const matcher = new RegExp(`^${m![1].replace(/\\\\/g, '\\')}$`);

  it.each([
    '/icons/apple-touch-icon.png', '/icons/icon-192x192.png', '/icons/maskable-icon-512x512.png', '/icons/favicon-32x32.png',
    '/icons/safari-pinned-tab.svg', '/icons/badge-96x96.png', '/icons/favicon.ico', '/favicon.ico', '/favicon.png',
    '/browserconfig.xml', '/manifest.json', '/images/logo.png', '/images/logo-mark.png',
  ])('%s skips the middleware', (p) => {
    expect(matcher.test(p)).toBe(false);
  });

  it('pages still run through it', () => {
    expect(matcher.test('/dashboard')).toBe(true);
    expect(matcher.test('/zzz-nope')).toBe(true);
  });
});

